# ──────────────────────────── Tag ────────────────────────────

class TestTag:
    def test_name_is_normalized(self):
        tag = Tag("  Shopping  ")
        assert tag.name == "shopping"

    def test_allows_hyphens_and_underscores(self):
        tag = Tag("my-tag_2")
        assert tag.name == "my-tag_2"

    @pytest.mark.parametrize("bad_name", ["", "   ", None])
    def test_rejects_empty_or_none(self, bad_name):
        with pytest.raises((ValueError, TypeError)):
            Tag(bad_name)

    def test_rejects_name_over_32_chars(self):
        with pytest.raises(ValueError, match="32 characters"):
            Tag("a" * 33)

    def test_accepts_exactly_32_chars(self):
        tag = Tag("a" * 32)
        assert len(tag.name) == 32

    @pytest.mark.parametrize("bad_char", ["a b", "a!b", "a@b", "a.b"])
    def test_rejects_illegal_characters(self, bad_char):
        with pytest.raises(ValueError, match="illegal character"):
            Tag(bad_char)

    def test_rejects_non_string_name(self):
        with pytest.raises(TypeError):
            Tag(123)


# ──────────────────────── TaskPriority ───────────────────────

class TestTaskPriority:
    def test_order_key_high_first(self):
        assert TaskPriority.order_key(TaskPriority.HIGH) < TaskPriority.order_key(TaskPriority.MEDIUM)
        assert TaskPriority.order_key(TaskPriority.MEDIUM) < TaskPriority.order_key(TaskPriority.LOW)

    def test_str_values(self):
        assert TaskPriority.LOW.value == "low"
        assert TaskPriority.MEDIUM.value == "medium"
        assert TaskPriority.HIGH.value == "high"


