class TestTask:
    def test_is_overdue_when_past_due(self, fixed_now):
        task = Task(id=1, title="x", due_at=fixed_now - timedelta(days=1), created_at=fixed_now)
        assert task.is_overdue(fixed_now) is True

    def test_not_overdue_when_future_due(self, fixed_now):
